# -*- coding: utf-8 -*-
import logging

from taf.fdsw.rc.interfaces.FDSW22A.autoconnection import AutoConfiguration22A
from taf.fdsw.rc.schemas.FDSW23B.autoconnection_parameters_builder_23b import \
    AutoconnectionParametersBuilder23B

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AutoConfiguration23B(AutoConfiguration22A):
    param_builder = AutoconnectionParametersBuilder23B

    def __init__(self, client):
        super(AutoConfiguration23B, self).__init__(client)

    def enable_propegate_existing_credentials(self, timeout=10):
        self._client.send(
            method='config.autoconnection.update',
            timeout=timeout,
            parameters={"pnpStatus": {"autoconfiguration": {"enabledOptions": ["preserveCredentials"]}}}
        )

    def disable_propegate_existing_credentials(self, timeout=10):
        self._client.send(
            method='config.autoconnection.update',
            timeout=timeout,
            parameters={"pnpStatus": {"autoconfiguration": {"enabledOptions": []}}}
        )
